    public static let ease: (Double, Double, Double, Double) = (0.16, 1, 0.3, 1)
    public static let easeIn: (Double, Double, Double, Double) = (0.4, 0, 1, 1)
    public static let easeOut: (Double, Double, Double, Double) = (0, 0, 0.2, 1)
    /// --tb-shadow-float as SwiftUI: radius = (blur + spread) / 2, y = y + spread / 2, colour --tb-shadow-ink, plus a hair ring in line.
    public static let floatShadowRadius: CGFloat = 10
    public static let floatShadowY: CGFloat = 10
}

/// TBD's established token names. They keep their call sites; their values now come from the kit.
public enum TBDTokens {
    /// window ground → TBDColor.paper
    public static var canvas: Color { TBDColor.paper }
    /// cards, fields and sheets (the kit's tile) → TBDColor.tile
    public static var paper: Color { TBDColor.tile }
    /// words → TBDColor.ink
    public static var ink: Color { TBDColor.ink }
    /// secondary text → TBDColor.muted
    public static var muted: Color { TBDColor.muted }
    /// hairlines and card rings; control edges use TBDColor.fieldEdge → TBDColor.line
    public static var border: Color { TBDColor.line }
    /// selected rows → TBDColor.tealWash
    public static var selected: Color { TBDColor.tealWash }
    /// hovered rows → TBDColor.plate
    public static var hover: Color { TBDColor.plate }
    /// text on the primary fill → TBDColor.primaryOn
    public static var onPrimary: Color { TBDColor.primaryOn }
    /// risk text and destructive labels (readable twin of brick) → TBDColor.brickInk
    public static var alert: Color { TBDColor.brickInk }
    /// teal text, icons and marks (readable twin of teal) → TBDColor.tealInk
    public static var accent: Color { TBDColor.tealInk }
    /// the primary action fill (ink; hover teal-deep) → TBDColor.primaryFill
    public static var fill: Color { TBDColor.primaryFill }

    /// Categories and charts (never chrome): the kit's group tones, plum → ink-soft.
    public static let data: [Color] = [TBDColor.toneTeal, TBDColor.toneMoss, TBDColor.toneWood, TBDColor.toneBrick, TBDColor.toneStone, TBDColor.inkSoft]

    /// C125/C126: ONE brick radius for everything you act with or that holds content; pills use Capsule().
    public enum Radius {
        public static let brick: CGFloat = TBDKit.radiusBrick
        public static let swatch: CGFloat = TBDKit.radiusSwatch
        public static let base: CGFloat = TBDKit.radiusBrick
        public static let xs: CGFloat = TBDKit.radiusBrick
        public static let sm: CGFloat = TBDKit.radiusBrick
    }
    public enum Stroke {
        public static let hairline: CGFloat = TBDKit.hair
        public static let bar: CGFloat = 2
        public static let focus: CGFloat = TBDKit.focusWidth
    }
    public enum Space {
        public static let xs: CGFloat = TBDKit.s1
        public static let sm: CGFloat = TBDKit.s2
        public static let md: CGFloat = TBDKit.s3
        public static let lg: CGFloat = TBDKit.s4
        public static let xl: CGFloat = TBDKit.s5
        public static let xxl: CGFloat = TBDKit.s6
        public static let xxxl: CGFloat = TBDKit.s8
    }
    public struct HardShadow: Sendable { public let x: CGFloat; public let y: CGFloat; public let opacity: Double }
    /// One Lift Rule: nothing in the flow casts a hard offset shadow. Kept at zero so old call sites draw nothing.
    public enum Shadow {
        public static let brickSm = HardShadow(x: 0, y: 0, opacity: 0)
        public static let brickMd = HardShadow(x: 0, y: 0, opacity: 0)
        public static let brickLg = HardShadow(x: 0, y: 0, opacity: 0)
    }
    /// macOS is pointer-only: controls are 36pt (the kit's small control); the main action of a form may use 44pt (--tb-target).
    public enum Control {
        public static let minHeight: CGFloat = 36
        public static let largeHeight: CGFloat = TBDKit.target
        public static let paddingX: CGFloat = 14
    }
    public enum Typography {
        /// page titles: 26pt / 900
        public static var display: Font { TBDFonts.nunito(TBDKit.textH2, TBDKit.weightHead) }
        /// section and card titles: 20pt / 800
        public static var title: Font { TBDFonts.nunito(TBDKit.textTitle, TBDKit.weightLabel) }
        /// reading text in dense panes: 15pt / 400
        public static var body: Font { TBDFonts.nunito(TBDKit.textLabel, TBDKit.weightBody) }
        /// every control label (buttons, fields, selects): 14pt / 800
        public static var control: Font { TBDFonts.nunito(TBDKit.textControl, TBDKit.weightLabel) }
        /// small sentence-case labels (no uppercase, no mono): 13pt / 800
        public static var label: Font { TBDFonts.nunito(TBDKit.textHint, TBDKit.weightLabel) }
        /// help text under a field: 14pt / 400
        public static var hint: Font { TBDFonts.nunito(TBDKit.textTag, TBDKit.weightBody) }
        /// pills: tags, chips, counts, segmented: 14pt / 700
        public static var tag: Font { TBDFonts.nunito(TBDKit.textTag, TBDKit.weightNav) }
        public static var mono: Font { .system(size: TBDKit.textHint, design: .monospaced) }
        public static let displayTracking: CGFloat = TBDKit.textH2 * TBDKit.trackingHead
        public static let titleTracking: CGFloat = 0
        public static let bodyTracking: CGFloat = 0
        public static let controlTracking: CGFloat = 0
        public static let labelTracking: CGFloat = 0
    }
}
